/**
 * STRUCTURAL PROOF AUDIT v2
 * 
 * This script does NOT summarize. It CALLS every function, TRACES every import,
 * and PROVES (or disproves) every architectural claim with actual execution results.
 * 
 * Each claim gets a PASS/FAIL with evidence.
 */

import crypto from 'crypto';

import { governanceLog } from '../_core/logger';
// ============================================================================
// SECTION 1: CAN WE IMPORT EVERY CLAIMED MODULE?
// ============================================================================

interface ProofResult {
  claim: string;
  category: string;
  passed: boolean;
  evidence: string;
  details?: any;
}

const results: ProofResult[] = [];

function record(category: string, claim: string, passed: boolean, evidence: string, details?: any) {
  results.push({ category, claim, passed, evidence, details });
}

async function runAudit() {
  governanceLog.info('═══════════════════════════════════════════════════════════════');
  governanceLog.info('  STRUCTURAL PROOF AUDIT v2 — EVERY CLAIM TESTED WITH EXECUTION');
  governanceLog.info('═══════════════════════════════════════════════════════════════\n');

  // ========================================================================
  // CATEGORY 1: MODULE IMPORTS — Do these files even exist and export what we claim?
  // ========================================================================

  governanceLog.info('▶ CATEGORY 1: MODULE IMPORTS\n');

  // 1a. Meaning Interpreter
  try {
    const mi = await import('./meaning-interpreter');
    const exports = Object.keys(mi);
    const required = ['interpretMeaning', 'computeCrossSurfaceCoherence'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'meaning-interpreter.ts exports interpretMeaning + computeCrossSurfaceCoherence', 
      missing.length === 0, 
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'meaning-interpreter.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1b. Human Interaction Model
  try {
    const him = await import('./human-interaction-model');
    const exports = Object.keys(him);
    const required = ['computeFromMeaningAnalysis', 'computeFromHumanContext', 'computeCombined', 'fullGovernancePipeline', 'getGeometryHistory'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'human-interaction-model.ts exports all 5 functions',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'human-interaction-model.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1c. Stability Response Engine
  try {
    const sre = await import('./stability-response-engine');
    const exports = Object.keys(sre);
    const required = ['generateStabilityResponse', 'applyStabilityModifications', 'stabilizeContent'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'stability-response-engine.ts exports all 3 functions',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'stability-response-engine.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1d. Human Context Model
  try {
    const hcm = await import('./human-context-model');
    const exports = Object.keys(hcm);
    const required = ['getOrCreateSession', 'recordContextEvent', 'getResponseCalibration'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'human-context-model.ts exports all 3 functions',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'human-context-model.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1e. Existence Classifier
  try {
    const ec = await import('./existence-classifier');
    const exports = Object.keys(ec);
    const required = ['getGravitoExistenceMap', 'classifyComponent'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'existence-classifier.ts exports getGravitoExistenceMap + classifyComponent',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'existence-classifier.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1f. Cognitive Feedback Loop
  try {
    const cfl = await import('./cognitive-feedback-loop');
    const exports = Object.keys(cfl);
    const required = ['runCognitiveFeedbackLoop', 'quickCognitiveAssessment'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'cognitive-feedback-loop.ts exports runCognitiveFeedbackLoop + quickCognitiveAssessment',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'cognitive-feedback-loop.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1g. Content Ingestion Bridge
  try {
    const cib = await import('./content-ingestion-cognition-bridge');
    const exports = Object.keys(cib);
    const required = ['ingestContent', 'batchIngest', 'getIngestionSummary'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'content-ingestion-cognition-bridge.ts exports ingestContent + batchIngest + getIngestionSummary',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'content-ingestion-cognition-bridge.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1h. Shield (MCP domain)
  try {
    const shield = await import('../agent/mcp/domains/shield');
    const exports = Object.keys(shield);
    const required = ['shieldReviewContent', 'runAnalyzers'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'shield.ts exports shieldReviewContent + runAnalyzers',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'shield.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1i. Persistence layer
  try {
    const persistence = await import('../agent/mcp/domains/persistence');
    const exports = Object.keys(persistence);
    const required = ['continuityOutcomesDb', 'continuitySelfModelDb', 'continuityInternalStateDb', 'continuityIdentityDb', 'continuityMemoryDb'];
    const missing = required.filter(r => !exports.includes(r));
    record('IMPORTS', 'persistence.ts exports all 5 continuity DB modules',
      missing.length === 0,
      missing.length === 0 ? `Found all: ${required.join(', ')}` : `Missing: ${missing.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'persistence.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1j. Continuity domains
  const continuityModules = [
    'continuity-outcomes',
    'continuity-self-model', 
    'continuity-internal-state',
    'continuity-identity',
    'continuity-memory',
  ];
  for (const mod of continuityModules) {
    try {
      const m = await import(`../agent/mcp/domains/${mod}`);
      const exports = Object.keys(m);
      record('IMPORTS', `${mod}.ts is importable with ${exports.length} exports`,
        exports.length > 0,
        `Exports: ${exports.join(', ')}`,
        { allExports: exports });
    } catch (e: unknown) {
      record('IMPORTS', `${mod}.ts is importable`, false, `Import failed: ${e.message}`);
    }
  }

  // 1k. HITL
  try {
    const hitl = await import('../agent/mcp/domains/hitl');
    const exports = Object.keys(hitl);
    record('IMPORTS', 'hitl.ts is importable',
      exports.length > 0,
      `Exports: ${exports.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'hitl.ts is importable', false, `Import failed: ${e.message}`);
  }

  // 1l. Surface Registry
  try {
    const sr = await import('./surface-registry');
    const exports = Object.keys(sr);
    record('IMPORTS', 'surface-registry.ts is importable',
      exports.length > 0,
      `Exports: ${exports.join(', ')}`,
      { allExports: exports });
  } catch (e: unknown) {
    record('IMPORTS', 'surface-registry.ts is importable', false, `Import failed: ${e.message}`);
  }

  // ========================================================================
  // CATEGORY 2: FUNCTION EXECUTION — Do these functions actually RUN and return expected shapes?
  // ========================================================================

  governanceLog.info('▶ CATEGORY 2: FUNCTION EXECUTION\n');

  // 2a. interpretMeaning — actually call it with content that SHOULD trigger overclaims
  try {
    const { interpretMeaning } = await import('./meaning-interpreter');
    const result = await interpretMeaning({
      content: 'Our product guarantees 100% uptime and never fails.',
      surfaceType: 'marketing',
      useLLM: false,
    });
    const hasRequiredFields = result.contentHash && result.surfaceType && 
      result.literalMeaning && result.coherenceScore !== undefined && 
      result.stabilityRisk !== undefined && result.concerns;
    record('EXECUTION', 'interpretMeaning() runs and returns MeaningAnalysis shape',
      !!hasRequiredFields,
      `contentHash=${result.contentHash}, stabilityRisk=${result.stabilityRisk}, concerns=${result.concerns.length}, coherence=${result.coherenceScore}`,
      { resultKeys: Object.keys(result) });

    // Verify it actually DETECTS overclaims
    record('EXECUTION', 'interpretMeaning() detects overclaims in "guarantees 100% uptime and never fails"',
      result.concerns.length > 0 && result.stabilityRisk > 0,
      `concerns=${result.concerns.length}, risk=${result.stabilityRisk}, types=[${result.concerns.map((c: any) => c.type).join(',')}]`);
  } catch (e: unknown) {
    record('EXECUTION', 'interpretMeaning() runs', false, `Error: ${e.message}`);
  }

  // 2b. computeFromMeaningAnalysis — actually call it
  try {
    const { interpretMeaning } = await import('./meaning-interpreter');
    const { computeFromMeaningAnalysis } = await import('./human-interaction-model');
    const meaning = await interpretMeaning({
      content: 'Test content for interaction model.',
      surfaceType: 'marketing',
      useLLM: false,
    });
    const snapshot = await computeFromMeaningAnalysis({
      analysis: meaning,
      entityId: 'audit-test-1',
      entityType: 'content',
    });
    const hasFields = snapshot.vector && snapshot.dominantPattern && 
      snapshot.stabilityIndex !== undefined && snapshot.trajectory;
    record('EXECUTION', 'computeFromMeaningAnalysis() runs and returns HumanInteractionModelSnapshot',
      !!hasFields,
      `dominantPattern=${snapshot.dominantPattern}, stabilityIndex=${snapshot.stabilityIndex}, trajectory=${snapshot.trajectory}`,
      { resultKeys: Object.keys(snapshot) });
  } catch (e: unknown) {
    record('EXECUTION', 'computeFromMeaningAnalysis() runs', false, `Error: ${e.message}`);
  }

  // 2c. generateStabilityResponse — actually call it
  try {
    const { interpretMeaning } = await import('./meaning-interpreter');
    const { generateStabilityResponse } = await import('./stability-response-engine');
    const meaning = await interpretMeaning({
      content: 'Buy now! Limited time! Guaranteed results!',
      surfaceType: 'email',
      useLLM: false,
    });
    const response = await generateStabilityResponse({
      content: 'Buy now! Limited time! Guaranteed results!',
      analysis: meaning,
      useLLM: false,
    });
    const hasFields = response.triggerId && response.strategy && 
      response.outputStabilityScore !== undefined && response.trustPreservationScore !== undefined;
    record('EXECUTION', 'generateStabilityResponse() runs and returns StabilityResponse',
      !!hasFields,
      `strategy=${response.strategy}, outputStability=${response.outputStabilityScore}, trustPreservation=${response.trustPreservationScore}, modifications=${response.contentModifications.length}`,
      { resultKeys: Object.keys(response) });
  } catch (e: unknown) {
    record('EXECUTION', 'generateStabilityResponse() runs', false, `Error: ${e.message}`);
  }

  // 2d. getResponseCalibration — actually call it
  try {
    const { getResponseCalibration } = await import('./human-context-model');
    const calibration = getResponseCalibration({
      sessionId: 'proof-audit-test',
      intent: 'exploring',
      confidenceLevel: 0.3,
      frictionLevel: 0.8,
      trustTrajectory: 'eroding',
      cognitiveLoad: 0.8,
      emotionalTrend: 'declining',
      stage: 'exploring',
      frictionType: 'confusion',
      needsReassurance: true,
      needsSimplification: true,
      needsGuidance: true,
      needsSpace: false,
      pageViewCount: 1,
      timeOnSite: 60,
      interactionDepth: 0.2,
      returnVisitor: false,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    });
    const hasFields = calibration.toneGuidance && calibration.complexityLevel && 
      calibration.urgency && calibration.approach;
    record('EXECUTION', 'getResponseCalibration() runs and returns calibration',
      !!hasFields,
      `complexity=${calibration.complexityLevel}, urgency=${calibration.urgency}, tone="${calibration.toneGuidance.slice(0, 60)}..."`,
      { resultKeys: Object.keys(calibration) });
  } catch (e: unknown) {
    record('EXECUTION', 'getResponseCalibration() runs', false, `Error: ${e.message}`);
  }

  // 2e. runCognitiveFeedbackLoop — THE BIG ONE
  try {
    const { runCognitiveFeedbackLoop } = await import('./cognitive-feedback-loop');
    const result = await runCognitiveFeedbackLoop({
      content: 'Our AI platform guarantees perfect results every time.',
      surfaceType: 'website',
      entityId: 'audit-loop-1',
      entityType: 'content',
      maxIterations: 2,
      useLLM: false,
    });
    const hasFields = result.loopId && result.iterations && result.finalIteration &&
      result.converged !== undefined && result.finalContent && 
      result.finalStabilityScore !== undefined && result.finalTrustScore !== undefined &&
      result.overallRiskLevel && result.crossSystemInsights;

    // Verify the loop actually ran multiple systems
    const iteration = result.finalIteration;
    const systemsRan = [
      iteration.meaningAnalysis ? 'meaning' : null,
      iteration.interactionSnapshot ? 'interaction' : null,
      iteration.stabilityResponse ? 'stability' : null,
    ].filter(Boolean);

    record('EXECUTION', 'runCognitiveFeedbackLoop() runs full circular flow',
      !!hasFields && systemsRan.length >= 3,
      `iterations=${result.totalIterations}, converged=${result.converged}, risk=${result.overallRiskLevel}, stability=${result.finalStabilityScore}, trust=${result.finalTrustScore}, systemsRan=[${systemsRan.join(',')}]`,
      { resultKeys: Object.keys(result), systemsRan });
  } catch (e: unknown) {
    record('EXECUTION', 'runCognitiveFeedbackLoop() runs', false, `Error: ${e.message}`);
  }

  // 2f. quickCognitiveAssessment
  try {
    const { quickCognitiveAssessment } = await import('./cognitive-feedback-loop');
    const result = await quickCognitiveAssessment({
      content: 'Simple product description.',
      surfaceType: 'website',
      entityId: 'audit-quick-1',
    });
    record('EXECUTION', 'quickCognitiveAssessment() runs fast path',
      !!result.riskLevel && result.stabilityScore !== undefined,
      `risk=${result.riskLevel}, stability=${result.stabilityScore}, pattern=${result.dominantPattern}`,
      { resultKeys: Object.keys(result) });
  } catch (e: unknown) {
    record('EXECUTION', 'quickCognitiveAssessment() runs', false, `Error: ${e.message}`);
  }

  // 2g. ingestContent
  try {
    const { ingestContent } = await import('./content-ingestion-cognition-bridge');
    const result = await ingestContent({
      content: 'Audit test: website content for ingestion bridge.',
      surfaceType: 'text',
    });
    const hasFields = result.ingestionId && result.surfaceType && result.normalizedContent && result.timestamp;
    record('EXECUTION', 'ingestContent() runs through cognitive pipeline',
      !!hasFields,
      `ingestionId=${result.ingestionId}, surfaceType=${result.surfaceType}, hasCognitiveResult=${!!result.cognitiveResult}, surfaceRegistered=${result.surfaceRegistered}`,
      { resultKeys: Object.keys(result) });
  } catch (e: unknown) {
    record('EXECUTION', 'ingestContent() runs', false, `Error: ${e.message}`);
  }

  // 2h. fullGovernancePipeline — end-to-end
  try {
    const { fullGovernancePipeline } = await import('./human-interaction-model');
    const result = await fullGovernancePipeline({
      content: 'Our platform helps businesses grow with AI-powered insights.',
      surfaceType: 'website',
      entityId: 'audit-pipeline-1',
      entityType: 'content',
      useLLM: false,
    });
    const hasFields = result.meaningAnalysis && result.geometrySnapshot && 
      result.stabilityResponse && result.stabilizedContent !== undefined;
    record('EXECUTION', 'fullGovernancePipeline() runs meaning→interaction→stability end-to-end',
      !!hasFields,
      `meaningConcerns=${result.meaningAnalysis.concerns.length}, pattern=${result.geometrySnapshot.dominantPattern}, strategy=${result.stabilityResponse.strategy}, wasModified=${result.wasModified}`,
      { resultKeys: Object.keys(result) });
  } catch (e: unknown) {
    record('EXECUTION', 'fullGovernancePipeline() runs', false, `Error: ${e.message}`);
  }

  // 2i. stabilizeContent — full pipeline
  try {
    const { stabilizeContent } = await import('./stability-response-engine');
    const result = await stabilizeContent({
      content: 'Buy now before the price doubles! Limited time offer!',
      surfaceType: 'marketing_email',
      useLLM: false,
    });
    record('EXECUTION', 'stabilizeContent() runs full meaning→stability→apply pipeline',
      !!result.originalContent && !!result.stabilizedContent && !!result.response,
      `strategy=${result.response.strategy}, wasModified=${result.wasModified}, outputStability=${result.response.outputStabilityScore}`,
      { resultKeys: Object.keys(result) });
  } catch (e: unknown) {
    record('EXECUTION', 'stabilizeContent() runs', false, `Error: ${e.message}`);
  }

  // 2j. getGravitoExistenceMap
  try {
    const { getGravitoExistenceMap } = await import('./existence-classifier');
    const map = getGravitoExistenceMap();
    record('EXECUTION', 'getGravitoExistenceMap() returns component map',
      map.components.length > 0 && map.materialized > 0,
      `total=${map.totalComponents}, materialized=${map.materialized}, intentional=${map.intentional}, latent=${map.latent}, maturity=${map.overallMaturity}`,
      { componentIds: map.components.map((c: any) => `${c.componentId}:${c.state}`) });
  } catch (e: unknown) {
    record('EXECUTION', 'getGravitoExistenceMap() runs', false, `Error: ${e.message}`);
  }

  // ========================================================================
  // CATEGORY 3: WIRING VERIFICATION — Does shield.ts ACTUALLY call cognitive loop?
  // ========================================================================

  governanceLog.info('▶ CATEGORY 3: WIRING VERIFICATION\n');

  // 3a. Verify shield.ts contains cognitive loop import
  try {
    const fs = await import('fs');
    const shieldSource = fs.readFileSync(
      new URL('../agent/mcp/domains/shield.ts', import.meta.url).pathname, 'utf-8'
    );
    const hasCognitiveImport = shieldSource.includes('cognitive-feedback-loop');
    const hasRunCognitiveCall = shieldSource.includes('runCognitiveFeedbackLoop');
    const hasNonBlocking = shieldSource.includes('.catch') || shieldSource.includes('non-blocking') || shieldSource.includes('void');
    record('WIRING', 'shield.ts imports cognitive-feedback-loop',
      hasCognitiveImport,
      hasCognitiveImport ? 'Found import of cognitive-feedback-loop in shield.ts' : 'NO import of cognitive-feedback-loop found');
    record('WIRING', 'shield.ts calls runCognitiveFeedbackLoop',
      hasRunCognitiveCall,
      hasRunCognitiveCall ? 'Found call to runCognitiveFeedbackLoop in shield.ts' : 'NO call to runCognitiveFeedbackLoop found');
    record('WIRING', 'shield.ts cognitive loop is non-blocking (fire-and-forget)',
      hasNonBlocking,
      hasNonBlocking ? 'Found non-blocking pattern (.catch/void) for cognitive loop' : 'Cognitive loop may be blocking');
  } catch (e: unknown) {
    record('WIRING', 'shield.ts source analysis', false, `Error reading source: ${e.message}`);
  }

  // 3b. Verify continuity-outcomes.ts has DB persistence
  try {
    const fs = await import('fs');
    const source = fs.readFileSync(
      new URL('../agent/mcp/domains/continuity-outcomes.ts', import.meta.url).pathname, 'utf-8'
    );
    const hasDbImport = source.includes('continuityOutcomesDb');
    const hasLogActionDb = source.includes('continuityOutcomesDb.logAction') || source.includes('continuityOutcomesDb.log');
    const hasTagOutcomeDb = source.includes('continuityOutcomesDb.tagOutcome') || source.includes('continuityOutcomesDb.tag');
    record('WIRING', 'continuity-outcomes.ts imports persistence DB',
      hasDbImport,
      hasDbImport ? 'Found continuityOutcomesDb import' : 'NO DB import found');
    record('WIRING', 'continuity-outcomes logAction persists to DB',
      hasLogActionDb,
      hasLogActionDb ? 'logAction calls DB persistence' : 'logAction does NOT call DB');
    record('WIRING', 'continuity-outcomes tagOutcome persists to DB',
      hasTagOutcomeDb,
      hasTagOutcomeDb ? 'tagOutcome calls DB persistence' : 'tagOutcome does NOT call DB');
  } catch (e: unknown) {
    record('WIRING', 'continuity-outcomes.ts source analysis', false, `Error: ${e.message}`);
  }

  // 3c. Verify continuity-self-model.ts has DB persistence (FIXED: check for upsertCapability)
  try {
    const fs = await import('fs');
    const source = fs.readFileSync(
      new URL('../agent/mcp/domains/continuity-self-model.ts', import.meta.url).pathname, 'utf-8'
    );
    const hasDbImport = source.includes('continuitySelfModelDb');
    // registerCapability calls continuitySelfModelDb.upsertCapability (not .registerCapability)
    const hasRegisterDb = source.includes('continuitySelfModelDb.upsertCapability');
    const hasUpdateDb = source.includes('continuitySelfModelDb.updateReliability');
    record('WIRING', 'continuity-self-model.ts imports persistence DB',
      hasDbImport,
      hasDbImport ? 'Found continuitySelfModelDb import' : 'NO DB import found');
    record('WIRING', 'continuity-self-model registerCapability persists to DB via upsertCapability',
      hasRegisterDb,
      hasRegisterDb ? 'registerCapability calls continuitySelfModelDb.upsertCapability' : 'registerCapability does NOT call DB');
    record('WIRING', 'continuity-self-model updateReliability persists to DB',
      hasUpdateDb,
      hasUpdateDb ? 'updateReliability calls continuitySelfModelDb.updateReliability' : 'updateReliability does NOT call DB');
  } catch (e: unknown) {
    record('WIRING', 'continuity-self-model.ts source analysis', false, `Error: ${e.message}`);
  }

  // 3d. Verify continuity-internal-state.ts has DB persistence
  try {
    const fs = await import('fs');
    const source = fs.readFileSync(
      new URL('../agent/mcp/domains/continuity-internal-state.ts', import.meta.url).pathname, 'utf-8'
    );
    const hasDbImport = source.includes('continuityInternalStateDb');
    const hasRecordDb = source.includes('continuityInternalStateDb.recordSignal') || source.includes('continuityInternalStateDb.record');
    record('WIRING', 'continuity-internal-state.ts imports persistence DB',
      hasDbImport,
      hasDbImport ? 'Found continuityInternalStateDb import' : 'NO DB import found');
    record('WIRING', 'continuity-internal-state recordStateSignal persists to DB',
      hasRecordDb,
      hasRecordDb ? 'recordStateSignal calls DB persistence' : 'recordStateSignal does NOT call DB');
  } catch (e: unknown) {
    record('WIRING', 'continuity-internal-state.ts source analysis', false, `Error: ${e.message}`);
  }

  // 3e. Verify cognitive-feedback-loop.ts actually calls all 5 systems
  // FIXED: The loop calls stabilizeContent which internally calls generateStabilityResponse
  try {
    const fs = await import('fs');
    const source = fs.readFileSync(
      new URL('./cognitive-feedback-loop.ts', import.meta.url).pathname, 'utf-8'
    );
    const systems = [
      { name: 'Meaning Interpreter', pattern: 'interpretMeaning' },
      { name: 'Human Interaction Model', pattern: 'computeFromMeaningAnalysis' },
      { name: 'Stability Response Engine', pattern: 'stabilizeContent', note: '(calls generateStabilityResponse internally)' },
      { name: 'Human Context Model', pattern: 'getResponseCalibration' },
      { name: 'Existence Classifier', pattern: 'getGravitoExistenceMap' },
    ];
    const found: string[] = [];
    const missing: string[] = [];
    for (const sys of systems) {
      if (source.includes(sys.pattern)) {
        found.push(`${sys.name}${sys.note ? ' ' + sys.note : ''}`);
      } else {
        missing.push(sys.name);
      }
    }
    record('WIRING', 'cognitive-feedback-loop.ts calls all 5 governance systems',
      missing.length === 0,
      missing.length === 0 
        ? `All 5 systems called: ${found.join(', ')}` 
        : `Missing calls to: ${missing.join(', ')}. Found: ${found.join(', ')}`,
      { found, missing });
  } catch (e: unknown) {
    record('WIRING', 'cognitive-feedback-loop.ts system calls analysis', false, `Error: ${e.message}`);
  }

  // 3f. Verify ingestion bridge calls cognitive feedback loop and has 8 surface types
  // FIXED: Check for actual ingestion surface types, not governance types
  try {
    const fs = await import('fs');
    const source = fs.readFileSync(
      new URL('./content-ingestion-cognition-bridge.ts', import.meta.url).pathname, 'utf-8'
    );
    const callsLoop = source.includes('runCognitiveFeedbackLoop');
    const callsRegistry = source.includes('registerSurface');
    // Ingestion surface types: text, url, email, chat, social, ad_copy, legal, api_docs
    const surfaceTypes = ['text', 'url', 'email', 'chat', 'social', 'ad_copy', 'legal', 'api_docs'];
    const foundTypes = surfaceTypes.filter(t => source.includes(`'${t}'`));
    const missingTypes = surfaceTypes.filter(t => !source.includes(`'${t}'`));
    record('WIRING', 'ingestion bridge calls runCognitiveFeedbackLoop',
      callsLoop,
      callsLoop ? 'Found call to runCognitiveFeedbackLoop' : 'NO call found');
    record('WIRING', 'ingestion bridge calls registerSurface',
      callsRegistry,
      callsRegistry ? 'Found call to registerSurface' : 'NO call found');
    record('WIRING', `ingestion bridge supports all 8 surface types`,
      missingTypes.length === 0,
      missingTypes.length === 0 
        ? `All 8 types found: ${foundTypes.join(', ')}` 
        : `Missing: ${missingTypes.join(', ')}. Found: ${foundTypes.join(', ')}`);
  } catch (e: unknown) {
    record('WIRING', 'ingestion bridge source analysis', false, `Error: ${e.message}`);
  }

  // ========================================================================
  // CATEGORY 4: EXISTENCE CLASSIFIER — CLAIMED vs ACTUAL
  // ========================================================================

  governanceLog.info('▶ CATEGORY 4: EXISTENCE CLASSIFIER VERIFICATION\n');

  try {
    const { getGravitoExistenceMap } = await import('./existence-classifier');
    const map = getGravitoExistenceMap();

    // Check each claimed materialized system
    const claimedMaterialized = [
      'human-context-model',
      'meaning-interpreter', 
      'stability-response',
      'human-interaction-model',
      'cognitive-feedback-loop',
      'ingestion-cognition-bridge',
      'continuity-engine',
      'shield-domain',
      'hitl-domain',
      'surface-registry',
      'existence-classifier',
    ];

    for (const id of claimedMaterialized) {
      const component = map.components.find((c: any) => c.componentId === id);
      if (component) {
        const evidenceStr = Array.isArray(component.evidence) 
          ? (component.evidence as unknown as string[]).join('; ').slice(0, 80)
            : typeof component.evidence === 'string' 
            ? (component.evidence as string).slice(0, 80)
            : JSON.stringify(component.evidence).slice(0, 80);
        record('EXISTENCE', `${id} is classified as materialized`,
          component.state === 'materialized',
          `Actual state: ${component.state}, evidence: ${evidenceStr}`);
      } else {
        record('EXISTENCE', `${id} exists in classifier`,
          false,
          `Component "${id}" not found in existence map`);
      }
    }

    record('EXISTENCE', `Overall maturity score reflects reality`,
      map.overallMaturity > 0.5,
      `maturity=${map.overallMaturity}, materialized=${map.materialized}/${map.totalComponents}`);
  } catch (e: unknown) {
    record('EXISTENCE', 'Existence classifier analysis', false, `Error: ${e.message}`);
  }

  // ========================================================================
  // CATEGORY 5: CROSS-SYSTEM DATA FLOW — Does data actually flow between systems?
  // ========================================================================

  governanceLog.info('▶ CATEGORY 5: CROSS-SYSTEM DATA FLOW\n');

  // 5a. Meaning → Interaction → Stability chain with content that SHOULD trigger concerns
  try {
    const { interpretMeaning } = await import('./meaning-interpreter');
    const { computeFromMeaningAnalysis } = await import('./human-interaction-model');
    const { generateStabilityResponse, applyStabilityModifications } = await import('./stability-response-engine');

    const content = 'Our AI guarantees zero errors and 100% accuracy in all scenarios.';

    // Step 1: Meaning
    const meaning = await interpretMeaning({ content, surfaceType: 'marketing', useLLM: false });
    const step1Ok = meaning.concerns.length > 0 && meaning.stabilityRisk > 0;

    // Step 2: Interaction (consumes meaning output)
    const interaction = await computeFromMeaningAnalysis({
      analysis: meaning,
      entityId: 'audit-flow-1',
      entityType: 'content',
    });
    const step2Ok = interaction.vector && interaction.dominantPattern;

    // Step 3: Stability (consumes meaning output)
    const stability = await generateStabilityResponse({
      content,
      analysis: meaning,
      useLLM: false,
    });
    const step3Ok = stability.strategy && stability.contentModifications;

    // Step 4: Apply modifications
    const stabilized = applyStabilityModifications(content, stability.contentModifications);
    const step4Ok = typeof stabilized === 'string';

    record('DATA_FLOW', 'Meaning → Interaction: meaning analysis flows into interaction model',
      !!step1Ok && !!step2Ok,
      `meaning.concerns=${meaning.concerns.length}, risk=${meaning.stabilityRisk} → interaction.pattern=${interaction.dominantPattern}`);
    record('DATA_FLOW', 'Meaning → Stability: meaning analysis flows into stability engine',
      !!step1Ok && !!step3Ok,
      `meaning.risk=${meaning.stabilityRisk} → stability.strategy=${stability.strategy}, modifications=${stability.contentModifications.length}`);
    record('DATA_FLOW', 'Stability → Content: modifications applied to content',
      !!step4Ok,
      `original="${content.slice(0, 40)}..." → stabilized="${stabilized.slice(0, 40)}..."`);
  } catch (e: unknown) {
    record('DATA_FLOW', 'Cross-system data flow', false, `Error: ${e.message}`);
  }

  // 5b. Full cognitive loop data flow
  try {
    const { runCognitiveFeedbackLoop } = await import('./cognitive-feedback-loop');
    const result = await runCognitiveFeedbackLoop({
      content: 'We guarantee our AI will never make mistakes and always delivers perfect results.',
      surfaceType: 'email',
      entityId: 'audit-flow-2',
      entityType: 'content',
      maxIterations: 2,
      useLLM: false,
    });

    const iter = result.finalIteration;
    const meaningFlowed = !!iter.meaningAnalysis;
    const interactionFlowed = !!iter.interactionSnapshot;
    const stabilityFlowed = !!iter.stabilityResponse;
    const insightsFlowed = result.crossSystemInsights.meaningConcerns !== undefined &&
      result.crossSystemInsights.stabilityStrategies !== undefined;

    record('DATA_FLOW', 'Cognitive loop: all 3 core systems produce output in each iteration',
      meaningFlowed && interactionFlowed && stabilityFlowed,
      `meaning=${meaningFlowed}, interaction=${interactionFlowed}, stability=${stabilityFlowed}`);
    record('DATA_FLOW', 'Cognitive loop: cross-system insights are aggregated',
      insightsFlowed,
      `meaningConcerns=${result.crossSystemInsights.meaningConcerns.length}, stabilityStrategies=${result.crossSystemInsights.stabilityStrategies.length}`);
    record('DATA_FLOW', 'Cognitive loop: convergence detection works',
      result.converged !== undefined && result.totalIterations > 0,
      `converged=${result.converged}, iterations=${result.totalIterations}`);
  } catch (e: unknown) {
    record('DATA_FLOW', 'Cognitive loop data flow', false, `Error: ${e.message}`);
  }

  // ========================================================================
  // PRINT RESULTS
  // ========================================================================

  governanceLog.info('\n═══════════════════════════════════════════════════════════════');
  governanceLog.info('  AUDIT RESULTS');
  governanceLog.info('═══════════════════════════════════════════════════════════════\n');

  const categories = [...new Set(results.map(r => r.category))];
  let totalPass = 0;
  let totalFail = 0;

  for (const cat of categories) {
    const catResults = results.filter(r => r.category === cat);
    const passed = catResults.filter(r => r.passed).length;
    const failed = catResults.filter(r => !r.passed).length;
    totalPass += passed;
    totalFail += failed;

    governanceLog.info(`\n── ${cat} (${passed}/${catResults.length} passed) ──`);
    for (const r of catResults) {
      const icon = r.passed ? '✅' : '❌';
      governanceLog.info(`  ${icon} ${r.claim}`);
      governanceLog.info(`     Evidence: ${r.evidence}`);
    }
  }

  governanceLog.info('\n═══════════════════════════════════════════════════════════════');
  governanceLog.info(`  FINAL SCORE: ${totalPass}/${totalPass + totalFail} PASSED`);
  if (totalFail > 0) {
    governanceLog.info(`  ⚠️  ${totalFail} CLAIMS FAILED — SEE DETAILS ABOVE`);
  } else {
    governanceLog.info(`  ✅ ALL CLAIMS VERIFIED WITH EXECUTION EVIDENCE`);
  }
  governanceLog.info('═══════════════════════════════════════════════════════════════\n');

  return { results, totalPass, totalFail };
}

export { runAudit };

// Run if executed directly
runAudit().catch(governanceLog.error);

